en:
//【村正】
<voice name='村正' class='村正さん' src='voice/md01/0130010a01'>
//《や、やっぱりいやらしいことする気だった
//のね！》
《I knew you were up to something dirty!》

pt:
//【村正】
<voice name='村正' class='村正さん' src='voice/md01/0130010a01'>
//《や、やっぱりいやらしいことする気だった
